import{_ as t,o as a,c as d,ah as s}from"./chunks/framework.C-FRNfAJ.js";const h=JSON.parse('{"title":"Démarrage","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/getting-started.md","filePath":"src/guide/getting-started.md"}'),i={name:"guide/getting-started.md"};function o(r,e,n,l,c,p){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="demarrage" tabindex="-1">Démarrage <a class="header-anchor" href="#demarrage" aria-label="Permalink to &quot;Démarrage&quot;">​</a></h1><p>Cette page installe Kura en local et décrit les commandes du quotidien.</p><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Prérequis&quot;">​</a></h2><ul><li><strong>PHP 8.3+</strong> avec les extensions <code>pdo_mysql</code> (ou <code>pdo_sqlite</code>), <code>mbstring</code>, <code>openssl</code>, <code>sodium</code>, <code>dom</code>, <code>xmlreader</code>, <code>fileinfo</code>, <code>zip</code> et <code>gd</code> (les deux dernières servent aux PDF et aux tableurs).</li><li><strong>Composer</strong> 2.</li><li><strong>Node.js 20.19+</strong> (voir <code>.nvmrc</code>) et <strong>pnpm</strong> 9+.</li><li><strong>SQLite</strong> (fourni avec PHP) pour le développement, ou MySQL pour se rapprocher de la production.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><p>La commande installe les dépendances PHP et JS, copie <code>.env.example</code> vers <code>.env</code>, génère la clé d&#39;application, lance les migrations, exécute les seeders, crée le lien de stockage et compile les assets.</p><p>Lance ensuite la stack de développement :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>L&#39;application est servie sur <code>http://localhost:8000</code>.</p><h2 id="compte-de-demonstration" tabindex="-1">Compte de démonstration <a class="header-anchor" href="#compte-de-demonstration" aria-label="Permalink to &quot;Compte de démonstration&quot;">​</a></h2><p>Le seeder crée un compte administrateur :</p><table tabindex="0"><thead><tr><th>Email</th><th>Mot de passe</th></tr></thead><tbody><tr><td><code>test@example.com</code></td><td><code>password</code></td></tr></tbody></table><p>Il porte le rôle <code>admin</code> : tu peux te connecter et ouvrir <code>/admin/users</code> immédiatement. Pour créer un autre administrateur sur une instance neuve :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users:create-admin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;nom&gt;&quot;</span></span></code></pre></div><p>Le mot de passe est demandé à l&#39;écran, jamais passé en argument.</p><h2 id="variables-d-environnement" tabindex="-1">Variables d&#39;environnement <a class="header-anchor" href="#variables-d-environnement" aria-label="Permalink to &quot;Variables d&#39;environnement&quot;">​</a></h2><p>Le fichier <code>.env.example</code> est commenté ligne à ligne. Les variables à connaître :</p><table tabindex="0"><thead><tr><th>Variable</th><th>Rôle</th><th>Défaut local</th></tr></thead><tbody><tr><td><code>APP_ENV</code>, <code>APP_URL</code></td><td>Environnement et URL de génération des liens</td><td><code>local</code>, <code>http://localhost:8000</code></td></tr><tr><td><code>DB_CONNECTION</code></td><td><code>sqlite</code>, <code>mysql</code> ou <code>pgsql</code></td><td><code>sqlite</code></td></tr><tr><td><code>MAIL_MAILER</code></td><td>Transport des emails</td><td><code>log</code> (écrit dans les logs)</td></tr><tr><td><code>QUEUE_CONNECTION</code></td><td>File d&#39;attente</td><td><code>database</code></td></tr><tr><td><code>NEXTBOXX_SITE_API_KEY</code></td><td>Clé attendue par l&#39;API du site NextBoxx</td><td>vide</td></tr><tr><td><code>SEVE_URL</code>, <code>SEVE_WS_TOKEN</code></td><td>Connexion aux web services Moodle</td><td>vides</td></tr><tr><td><code>WHATSAPP_TOKEN</code>, <code>WHATSAPP_PHONE_NUMBER_ID</code></td><td>WhatsApp Business Cloud API</td><td>vides</td></tr></tbody></table><p>Tant que les variables Sève et WhatsApp sont vides, Kura fonctionne normalement : les changements destinés à Sève restent dans la file et les messages partent uniquement par email.</p><h2 id="commandes-utiles" tabindex="-1">Commandes utiles <a class="header-anchor" href="#commandes-utiles" aria-label="Permalink to &quot;Commandes utiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Commande</th><th>Effet</th></tr></thead><tbody><tr><td><code>composer dev</code></td><td>Serveur, file d&#39;attente, Vite et logs en parallèle</td></tr><tr><td><code>composer test</code></td><td>Pint, Larastan puis Pest — la porte de la CI</td></tr><tr><td><code>composer ci:check</code></td><td>Ajoute ESLint, Prettier et <code>vue-tsc</code> à la vérification</td></tr><tr><td><code>pnpm run build</code></td><td>Compile les assets de production</td></tr><tr><td><code>php artisan migrate</code></td><td>Applique les migrations</td></tr><tr><td><code>php artisan test --compact</code></td><td>Lance la suite Pest</td></tr><tr><td><code>php artisan users:create-admin</code></td><td>Crée un compte administrateur</td></tr><tr><td><code>php artisan seve:client</code></td><td>Enregistre Sève comme client OAuth et affiche son secret</td></tr></tbody></table><h2 id="premiers-pas-dans-l-application" tabindex="-1">Premiers pas dans l&#39;application <a class="header-anchor" href="#premiers-pas-dans-l-application" aria-label="Permalink to &quot;Premiers pas dans l&#39;application&quot;">​</a></h2><ol><li>Connecte-toi avec le compte de démonstration.</li><li>Ouvre <strong>Administration → Utilisateurs</strong> (<code>/admin/users</code>) pour créer les comptes de l&#39;équipe et attribuer les rôles.</li><li>Renseigne les <strong>réglages</strong> (<code>/admin/settings</code>) : mentions de facture, seuils de mention du certificat, seuils de rentabilité.</li><li>Publie un premier référentiel dans le <strong>catalogue</strong>, valide sa banque QCM, puis ouvre une <strong>cohorte</strong>.</li><li>Dépose une candidature depuis l&#39;API ou depuis l&#39;interface pour dérouler le parcours complet.</li></ol><h2 id="et-ensuite" tabindex="-1">Et ensuite <a class="header-anchor" href="#et-ensuite" aria-label="Permalink to &quot;Et ensuite&quot;">​</a></h2><ul><li><a href="/kura-guide/guide/architecture.html">Architecture</a> pour comprendre le code.</li><li><a href="/kura-guide/guide/development.html">Développement</a> pour les conventions et les tests.</li><li><a href="/kura-guide/guide/deployment.html">Déploiement</a> pour la mise en production.</li></ul>',26)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
